import type { Object3D, Scene } from "three";

export type Vec3 = [number, number, number];

// ---------- timeline (generated by scripts/build-timeline.ts)
export type Word = { w: string; s: number; e: number };
export type Chunk = { s: number; e: number; words: Word[] };
export type Line = { n: number; s: number; e: number; text: string };
export type ShotSpan = { id: string; s: number; e: number };
export type Timeline = {
  dur: number;
  lines: Line[];
  chunks: Chunk[];
  shots: ShotSpan[];
};

/** Read-only helpers every video gets for timing its animation to the voiceover. */
export type Ctx = {
  tl: Timeline;
  /** Timing of script line n (1-based). */
  L: (n: number) => Line;
  /** Timing of a shot by id. */
  shot: (id: string) => ShotSpan;
};

// ---------- shots
export type CamPose = { position: Vec3; target: Vec3 };

export type CalloutDef = {
  text: string;
  /** World-space point the leader line points at (may move over time). */
  anchor: (t: number) => Vec3;
  /** Seconds (absolute) when it appears / disappears. */
  at: number;
  until?: number;
  /** Label offset from the anchor, in px. */
  dx: number;
  dy: number;
  variant?: "default" | "orange" | "red";
};

export type ChipState = { key: string; value: string; unit?: string; red?: boolean };

export type ShotDef = {
  /** Small mono label above the title, e.g. "LANGKAH 1". */
  label: string;
  /** Title; wrap highlighted words in *asterisks*, use \n for a line break. */
  title: string;
  /** Small badge top-right under the brand, e.g. "ILUSTRASI". */
  tag?: string;
  camera: (t: number) => CamPose;
  callouts?: CalloutDef[];
  chip?: (t: number) => ChipState | null;
};

// ---------- world
export type WorldApi = {
  root: Object3D;
  /** Called every frame before rendering. Must be a pure function of its inputs. */
  update: (t: number, shotId: string, pose: CamPose, scene: Scene) => void;
};

export type VideoDef = {
  id: string;
  brand: { prefix: string; accent: string };
  fov: number;
  timeline: Timeline;
  voice: string; // path inside public/
  music?: { src: string; volume: number };
  cta?: { text: string; fromLine: number };
  shots: (ctx: Ctx) => Record<string, ShotDef>;
  createWorld: (ctx: Ctx) => WorldApi;
};
